<script lang="ts">
  import {enhance} from '$app/forms';
  let {data,form}=$props();
  let pending=$state(false);
  const enhanceForm=()=>{pending=true;return async({update}:any)=>{try{await update()}finally{pending=false}}};
</script>
<svelte:head><title>{data.config.title}</title><meta name="description" content={data.config.description}/><link rel="stylesheet" href="/style.css"/><link rel="icon" href="/favicon.svg"/></svelte:head>
<header class="site-header"><a class="wordmark" href="/">{data.config.title}</a><a class="quiet-link" href="/admin">Operator</a></header><main><section class="hero"><div><div class="eyebrow">{data.config.eyebrow}</div><h1>{data.config.headline}</h1><p class="intro">{data.config.description}</p>{#each data.config.details as [key,value]}<div class="detail"><small>{key}</small><strong>{value}</strong></div>{/each}</div><form class="card" method="post" use:enhance={enhanceForm}><h2>{data.config.button}</h2>{#if form?.message}<div role={form.ok?'status':'alert'} class:notice={true} class:error={!form.ok}>{form.message}</div>{/if}{#each data.config.fields as field}<label><span>{field.label}</span>{#if field.type==='textarea'}<textarea name={field.name} rows="4" maxlength="2000" required></textarea>{:else if field.options}<select name={field.name} required><option value="">Choose an option</option>{#each field.options as option}<option value={option.value}>{option.label}</option>{/each}</select>{:else}<input type={field.type} name={field.name} maxlength="300" required/>{/if}</label>{/each}<button disabled={pending}>{pending?'Saving…':data.config.button}</button><p class="form-note">{data.config.formNote}</p></form></section>{#if data.model.rows.length}<section class="listing"><h2>The idea board</h2>{#each data.model.rows as row}<article class="list-item"><h3>{row.title}</h3><p>{row.description}</p></article>{/each}</section>{/if}</main><footer>Small tools, useful work. <span>SvelteKit</span></footer>
